// audio.js — every sound is synthesized with WebAudio: no audio files, so
// the no-network gate is trivially satisfied. The context starts on the
// first user gesture; until then calls are silent no-ops (the screenshot
// harness never clicks, and that is fine).
let ctx = null;
let master = null;
let muted = false;

function ac(G) {
  try {
    if (!ctx) {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
      master = ctx.createGain();
      master.gain.value = 0.35;
      master.connect(ctx.destination);
    }
    if (ctx.state === 'suspended') void ctx.resume();
    return ctx;
  } catch {
    return null;
  }
}

function tone(G, freq, dur, type = 'sine', vol = 0.5, slideTo = 0) {
  const c = ac(G);
  if (!c || muted) return;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, c.currentTime);
  if (slideTo > 0) o.frequency.exponentialRampToValueAtTime(slideTo, c.currentTime + dur);
  g.gain.setValueAtTime(vol, c.currentTime);
